const floatBuffer = new ArrayBuffer(8);
const floatView = new DataView(floatBuffer);
export const MaxFloat64 = Number.MAX_VALUE;
export const MaxInt = 9223372036854775807n;
export const MaxInt32 = 2_147_483_647;
export const MaxInt64 = 9223372036854775807n;
export const MinInt = -9223372036854775808n;
export const MinInt64 = -9223372036854775808n;
export function Abs(value) {
    return Math.abs(value);
}
export function Ceil(value) {
    return Math.ceil(value);
}
export function Copysign(magnitude, sign) {
    const absolute = Math.abs(magnitude);
    return sign < 0 || Object.is(sign, -0) ? -absolute : absolute;
}
export function Float64bits(value) {
    floatView.setFloat64(0, value, false);
    return floatView.getBigUint64(0, false);
}
export function Float32bits(value) {
    floatView.setFloat32(0, value, false);
    return floatView.getUint32(0, false);
}
export function Float32frombits(value) {
    floatView.setUint32(0, value, false);
    return floatView.getFloat32(0, false);
}
export function Float64frombits(value) {
    floatView.setBigUint64(0, value, false);
    return floatView.getFloat64(0, false);
}
export function Floor(value) {
    return Math.floor(value);
}
export function Inf(sign) {
    return sign >= 0n ? Number.POSITIVE_INFINITY : Number.NEGATIVE_INFINITY;
}
export function IsInf(value, sign) {
    if (sign > 0n) {
        return value === Number.POSITIVE_INFINITY;
    }
    if (sign < 0n) {
        return value === Number.NEGATIVE_INFINITY;
    }
    return value === Number.POSITIVE_INFINITY || value === Number.NEGATIVE_INFINITY;
}
export function IsNaN(value) {
    return Number.isNaN(value);
}
export function Log2(value) {
    return Math.log2(value);
}
export function Log10(value) {
    return Math.log10(value);
}
export function Min(left, right) {
    return Math.min(left, right);
}
export function Mod(dividend, divisor) {
    return dividend % divisor;
}
export function NaN() {
    return Number.NaN;
}
export function Pow(base, exponent) {
    return Math.pow(base, exponent);
}
export function Round(value) {
    if (!Number.isFinite(value) || value === 0) {
        return value;
    }
    const truncated = Math.trunc(value);
    return Math.abs(value - truncated) < 0.5
        ? truncated
        : truncated + Math.sign(value);
}
export function Signbit(value) {
    return value < 0 || Object.is(value, -0);
}
export function Trunc(value) {
    return Math.trunc(value);
}
